// Home Locator CRM data/actions
export const STATUS=['Initial','RNR','Verified','Site Visit Scheduled','Site Visit Done','Not Interested','Booked','EOI','Hold','Re-Sale','Duplicate','Project Mismatch','Cancelled'];
export const SELLER_STATUS=['Initial','Verified','Active','Booked','Closed','Rejected'];
export const SOURCES=['Manual','Website','Walk-in','Referral','Campaign'];
export const REASONS=['Budget mismatch','No response','Location mismatch','Timeline','Duplicate','Other'];
export const MODULES=['Leads','Sellers / Data','Process','Admin','Marketing','Channel Partners','Notice Board','HR','Sales','Digital','Settings'];
export const MENUS=[['Leads','Leads'],['Sellers / Data',[['Sellers','Sellers'],['Data','Data']]],['Process',[['RNR','RNR'],['Transferred','Transferred'],['SVS','SVS'],['SVD','SVD'],['Not Interested','Not Interested'],['Lost','Lost']]],['Admin',[['Assets','Assets'],['Allotment','Allotment'],['Office','Office']]],['Marketing','Campaigns'],['Channel Partners','Channel Partners'],['Notice Board','Notice Board'],['HR',[['Leaves','Leaves'],['Attendance List','Attendance'],['Candidate','Candidate']]],['Sales',[['Sales History','Sales History'],['Incentives','Incentives'],['CRM','Sales CRM'],['Reimbursement','Reimbursement']]],['Digital',[['Calendar','Calendar'],['Tasks','Tasks'],['Digital Spends','Digital Spends']]],['Settings','Settings']];
export const SETTINGS=['users','projects','knowledge','assigned projects','inventory','notices','csv','bulk leads','bulk data','cost sheet'];
export const PROCESS=['RNR','Transferred','SVS','SVD','Not Interested','Lost'];
export const statusOf=l=>l.stage||'Initial';
export const agentNames=s=>[...new Set(s.users.map(u=>u.name))];
export const projectNames=s=>[...new Set(s.projects.map(p=>p.name))];
const clone=x=>structuredClone(x);
const id=(p,n)=>`${p}-${String(n).padStart(3,'0')}`;
export function seedCRM(now=new Date().toISOString()){
 const users=[{id:'USR-001',name:'Manager',role:'Manager'},{id:'USR-002',name:'Anjali',role:'Agent'},{id:'USR-003',name:'Rahul',role:'Agent'}];
 const projects=[{id:'PRJ-001',name:'Cedar Heights'},{id:'PRJ-002',name:'Palm Residency'}];
 const leads=Array.from({length:8},(_,i)=>({id:id('LEAD',i+1),name:['Arun Kumar','Priya Rao','Vikram Singh','Meena Devi','Kiran Reddy','Sandeep Rao','Nisha Patel','Ravi Teja'][i],phone:`9000000${100+i}`,email:`lead${i+1}@example.com`,project:projects[i%2].name,stage:i<3?'Initial':i===3?'Qualified':'Verified',owner:users[(i%2)+1].name,coOwner:'',createdAt:now,tags:'',purpose:'End Use',configuration:'2 BHK'}));
 const tasks=leads.filter(l=>!['Booked','Lost','Not Interested'].includes(l.stage)).map((l,i)=>({id:id('TASK',i+1),leadId:l.id,owner:l.owner,kind:'Follow-up',due:new Date(Date.parse(now)+(i+1)*86400000).toISOString(),status:'Open'}));
 return {users,projects,leads,tasks,events:[],visits:[],sources:[],inventory:[],sales:[],modules:{}};
}
export function applyCRM(state,action,now=new Date().toISOString(),actor='Manager'){
 const s=clone(state); const d=action.data||{}; let resultId=action.leadId||action.sourceId; let message='Saved.';
 if(action.type==='createLead'){
  const phone=String(d.phone||'').replace(/\D/g,''); if(!d.name||!phone)throw Error('Name and phone are required.'); if(s.leads.some(l=>l.phone.replace(/\D/g,'')===phone))throw Error('A lead with this phone already exists.');
  resultId=id('LEAD',s.leads.length+1); const l={id:resultId,name:d.name,phone:d.phone,email:d.email||'',project:d.project||'',stage:'Initial',owner:d.owner||agentNames(s).find(x=>x!=='Manager')||actor,coOwner:'',createdAt:now,tags:d.tags||'',purpose:d.purpose||'',configuration:d.configuration||''}; s.leads.push(l); s.tasks.push({id:id('TASK',s.tasks.length+1),leadId:resultId,owner:l.owner,kind:'First call',due:new Date(Date.parse(now)+86400000).toISOString(),status:'Open'}); message='Lead created.';
 } else if(action.type==='updateLead'){const l=s.leads.find(x=>x.id===action.leadId); if(!l)throw Error('Lead not found.'); Object.assign(l,d); message='Lead updated.';
 } else if(action.type==='call'){const l=s.leads.find(x=>x.id===action.leadId); if(!l)throw Error('Lead not found.'); if(!d.notes)throw Error('Requirement: notes.'); if(!d.next||Date.parse(d.next)<=Date.parse(now))throw Error('Next follow-up must be in the future.'); l.stage=d.outcome==='Connected'?'Qualified':d.outcome==='RNR'?'Contacting':l.stage; s.events.push({id:id('EVT',s.events.length+1),leadId:l.id,type:'Call',at:now,notes:d.notes,outcome:d.outcome}); s.tasks=s.tasks.filter(t=>!(t.leadId===l.id&&t.status==='Open')); s.tasks.push({id:id('TASK',s.tasks.length+1),leadId:l.id,owner:l.owner,kind:'Follow-up',due:d.next,status:'Open'}); message='Call recorded.';
 } else if(action.type==='scheduleVisit'){const l=s.leads.find(x=>x.id===action.leadId); if(!l||!['Qualified','Verified'].includes(l.stage))throw Error('Qualify the lead before scheduling a visit.'); s.visits.push({id:id('VISIT',s.visits.length+1),leadId:l.id,project:d.project,when:d.when,owner:l.owner,status:'Scheduled',notes:d.notes||''}); l.stage='Site Visit Scheduled'; message='Visit scheduled.';
 } else if(action.type==='completeVisit'){const v=s.visits.find(x=>x.leadId===action.leadId&&x.status==='Scheduled'); if(!v)throw Error('No scheduled visit.'); if(Date.parse(now)<Date.parse(v.when))throw Error('Advance the demo clock to complete the visit.'); v.status='Completed'; v.completedAt=now; const l=s.leads.find(x=>x.id===action.leadId); l.stage='Site Visit Done'; message='Visit completed.';
 } else if(action.type==='transfer'){const l=s.leads.find(x=>x.id===action.leadId); if(!l)throw Error('Lead not found.'); l.owner=d.owner; l.coOwner=d.coOwner||''; s.tasks.filter(t=>t.leadId===l.id&&t.status==='Open').forEach(t=>t.owner=l.owner); s.visits.filter(v=>v.leadId===l.id&&v.status==='Scheduled').forEach(v=>v.owner=l.owner); message='Lead transferred.';
 } else if(action.type==='close'){const l=s.leads.find(x=>x.id===action.leadId); if(!l)throw Error('Lead not found.'); if(action.data.outcome==='Lost'&&!d.reason)throw Error('Lost reason is required.'); if(action.data.outcome==='Won'&&Number(d.saleValue)<=0)throw Error('Sale value is required.'); l.stage=action.data.outcome==='Won'?'Booked':action.data.outcome==='Lost'?'Lost':action.data.outcome; l.saleValue=Number(d.saleValue||0); s.tasks.filter(t=>t.leadId===l.id).forEach(t=>t.status='Closed'); if(action.data.outcome==='Won')s.sales.push({id:id('SALE',s.sales.length+1),leadId:l.id,value:l.saleValue,closedDate:d.closedDate||now}); message='Lead closed.';
 } else if(action.type==='followup'){const l=s.leads.find(x=>x.id===action.leadId); if(!l||['Lost','Booked','Not Interested'].includes(l.stage))throw Error('Cannot add a follow-up to a closed lead.'); if(!d.next||Date.parse(d.next)<=Date.parse(now))throw Error('Next follow-up must be in the future.'); s.tasks.filter(t=>t.leadId===l.id&&t.status==='Open').forEach(t=>t.status='Closed'); s.tasks.push({id:id('TASK',s.tasks.length+1),leadId:l.id,owner:l.owner,kind:'Follow-up',due:d.next,status:'Open'}); message='Follow-up saved.';
 } else if(action.type==='convert'){const src=s.sources.find(x=>x.id===action.sourceId)||{id:action.sourceId}; if(d.target==='Inventory'&&(!d.project||!d.unit||!d.bhk||!d.area||!d.price))throw Error('Inventory project, unit, configuration, area and price are required.'); if(d.target==='Lead'){const existing=s.leads.find(l=>l.origin?.id===action.sourceId); if(existing)return {state:s,resultId:existing.id,message:'Already converted.'}; resultId=id('LEAD',s.leads.length+1); s.leads.push({id:resultId,name:src.name||'Converted lead',phone:src.phone||'9000000999',email:src.email||'',project:src.project||'',stage:'Initial',owner:actor,coOwner:'',createdAt:now,origin:src});} else {resultId=id('INV',s.inventory.length+1);s.inventory.push({id:resultId,origin:src,project:d.project,unit:d.unit,bhk:d.bhk,area:Number(d.area),price:Number(d.price)});} message='Converted successfully.';
 }
 return {state:s,resultId,message};
}
export const parseCSV=text=>String(text).trim().split(/\r?\n/).map(r=>r.split(',').map(x=>x.trim()));
